<script setup lang="ts">
import {ref,nextTick} from 'vue';import {api} from './api';
type Place={code:string;name:string;updated_at:string};type Related={code:string;name:string;region:string|null};
const props=defineProps<{place:Place}>(),emit=defineEmits<{deleted:[]}>();
const target=ref<Place|null>(null),children=ref<Related[]>([]),parentOptions=ref<Related[]>([]),childAction=ref<'detach'|'transfer'>('detach'),newParentCode=ref(''),busy=ref(false),loading=ref(false),error=ref(''),cancelButton=ref<HTMLButtonElement>();
const childrenToken=ref('');let previewGeneration=0;
async function open(){const generation=++previewGeneration;const code=props.place.code;target.value={code,name:props.place.name,updated_at:props.place.updated_at};childrenToken.value='';children.value=[];parentOptions.value=[];childAction.value='detach';newParentCode.value='';error.value='';loading.value=true;await nextTick();cancelButton.value?.focus();try{const result=await api('/places/'+code+'/delete-preview');if(generation===previewGeneration&&target.value?.code===code){children.value=result.children;parentOptions.value=result.parent_options;childrenToken.value=result.children_token;}}catch(e){if(generation===previewGeneration)error.value=(e as Error).message;}finally{if(generation===previewGeneration)loading.value=false;}}
function close(){if(!busy.value){previewGeneration++;target.value=null;childrenToken.value='';}}
async function remove(){if(!target.value||busy.value||loading.value||!childrenToken.value)return;if(children.value.length&&childAction.value==='transfer'&&!newParentCode.value){error.value='请选择新的父地点';return;}busy.value=true;error.value='';const current=target.value;try{await api('/places/'+current.code+'/delete',{expected_updated_at:current.updated_at,expected_children_token:childrenToken.value,child_action:childAction.value,new_parent_code:childAction.value==='transfer'?newParentCode.value:null});target.value=null;emit('deleted');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><button type="button" class="danger-button" @click="open">删除地点</button><div v-if="target" class="action-shade"><section class="action-dialog" role="alertdialog" aria-modal="true" aria-label="删除地点" @keydown.esc.prevent="close"><h2>移入回收站</h2>
 <p>确认删除「{{target.name}}」？地点将移入回收站，可随时恢复；坐标历史、名称历史、排序、路线和其他关联资料不会删除。</p>
 <p v-if="loading" role="status">正在检查子地点…</p>
 <template v-else-if="children.length"><h3>需要处理 {{children.length}} 个子地点</h3><ul class="delete-child-list"><li v-for="child in children" :key="child.code"><strong>{{child.code}} {{child.name}}</strong><small>{{child.region||'区域未记录'}}</small></li></ul>
  <fieldset class="child-action-options"><legend>子地点处理方式</legend><label class="choice"><input v-model="childAction" type="radio" value="detach">保留子地点并解除父级关系（默认）</label><label class="choice"><input v-model="childAction" type="radio" value="transfer">将子地点转移到其他现有地点</label>
   <label v-if="childAction==='transfer'">新的父地点<select v-model="newParentCode" required aria-label="新的父地点"><option value="">请选择</option><option v-for="option in parentOptions" :key="option.code" :value="option.code">{{option.code}} {{option.name}}{{option.region?' · '+option.region:''}}</option></select></label>
  </fieldset><p class="muted">不会删除任何子地点；恢复当前地点后也不会自动改回子地点父级。</p></template>
 <p v-else-if="!loading&&childrenToken">该地点没有未删除的子地点。</p><p v-if="error" class="error" role="alert">{{error}}</p><div class="actions"><button ref="cancelButton" type="button" class="secondary" :disabled="busy" @click="close">取消</button><button type="button" class="danger-button" :disabled="busy||loading||!childrenToken||(children.length>0&&childAction==='transfer'&&!newParentCode)" @click="remove">确认删除地点</button></div></section></div></template>
